    """
    Returns True if any two numbers in list are within given threshold.
    :param numbers: 'List[float]' to check if neighboring values are close
    :param threshold: 'float' representing if the numbers are close enough
    :return: True if any two in the list satisfy the threshold, False otherwise
    """
    if not numbers or len(numbers) < 2:
        return False

    for idx in range(len(numbers) - 1):
        if abs(numbers[idx] - numbers[idx + 1]) < threshold:
